from collections import deque
out=[row[:] for row in rows]
# Clear source motifs in the top workspace.
for r in range(14):
    for c in range(24):
        if out[r][c] != 1:
            out[r][c]=1
spec={2:(14,18,8),4:(20,24,2),8:(25,28,6)}
# Find each source-color component in the original top workspace and place its mask at the bottom of its matching panel.
for color,(top,bottom,mark) in spec.items():
    seen=set()
    for r in range(14):
        for c in range(24):
            if rows[r][c]!=color or (r,c) in seen: continue
            comp=[]; q=deque([(r,c)]); seen.add((r,c))
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<14 and 0<=nx<24 and rows[ny][nx]==color and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            shift=bottom-max(y for y,x in comp)
            coords=[]
            for y,x in comp:
                yy=y+shift
                out[yy][x]=mark
                coords.append((yy,x))
            print('color',color,'size',len(comp),'srcbbox',(min(y for y,x in comp),max(y for y,x in comp),min(x for y,x in comp),max(x for y,x in comp)),'outbbox',(min(y for y,x in coords),max(y for y,x in coords),min(x for y,x in coords),max(x for y,x in coords)))
